INSERT INTO "notifications" ("id", "event", "channel", "is_enabled", "subject", "template", "created_at", "updated_at", "name", "conditions", "merchant_id", "wa_name", "wa_language", "wa_status", "wa_reason", "wa_template_id", "wa_params", "wa_body", "wa_version", "wa_checked_at", "reply_buttons", "wa_buttons") VALUES ('69ad7f48-2d25-47a6-a16d-980e857a68c6', 'PRE_ORDER_CONFIRMED', 'EMAIL', 0, 'Pre-order {{ order.name }} confirmed', replace('{% assign accent = shop.accent_color | default: "#111827" %}<!doctype html>⏎<html lang="en">⏎<head>⏎<meta charset="utf-8">⏎<meta name="viewport" content="width=device-width, initial-scale=1">⏎<title>Your pre-order is confirmed</title>⏎</head>⏎<body style="margin:0;padding:0;background:#f4f5f7;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f5f7;">⏎<tr><td align="center" style="padding:32px 12px;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;">⏎<tr><td style="padding:28px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>⏎<td>{% if shop.logo_url %}<img src="{{ shop.logo_url }}" alt="{{ shop.name }}" height="36" style="display:block;height:36px;max-width:180px;border:0;">{% else %}<span style="font-size:20px;font-weight:700;color:#111827;">{{ shop.name }}</span>{% endif %}</td>⏎<td align="right" style="font-size:13px;color:#6b7280;">{% if order.name %}Order {{ order.name }}{% endif %}</td>⏎</tr></table>⏎</td></tr>⏎<tr><td style="padding:24px 32px 4px;">⏎<h1 style="margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;">Your pre-order is confirmed</h1>⏎<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">Hi {{ customer.first_name | default: "there" }}, your pre-order {{ order.name }} is confirmed. We will ship it as soon as it arrives in stock.</p>⏎</td></tr>⏎{% if order.status_url %}<tr><td style="padding:12px 32px 4px;">⏎<a href="{{ order.status_url }}" style="display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;">View your order</a>⏎</td></tr>{% endif %}⏎<tr><td style="padding:8px 32px 0;">⏎<p style="margin:0 0 8px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;">Order summary</p>⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-top:1px solid #e5e7eb;">⏎{% for item in order.line_items %}<tr>⏎<td width="56" style="padding:12px 12px 12px 0;border-bottom:1px solid #f3f4f6;vertical-align:top;">{% if item.image_url %}<img src="{{ item.image_url }}" alt="" width="48" height="48" style="display:block;width:48px;height:48px;border-radius:8px;object-fit:cover;border:1px solid #e5e7eb;">{% endif %}</td>⏎<td style="padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;line-height:1.4;color:#111827;vertical-align:top;">{{ item.title }}{% if item.variant_title %}<br><span style="color:#6b7280;font-size:13px;">{{ item.variant_title }}</span>{% endif %}<br><span style="color:#6b7280;font-size:13px;">Qty {{ item.quantity }}</span></td>⏎<td align="right" style="padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;color:#111827;vertical-align:top;white-space:nowrap;">{{ item.line_price | money }}</td>⏎</tr>{% endfor %}⏎</table>⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-top:8px;">⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">Subtotal</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.subtotal_price | money }}</td></tr>⏎{% if order.discount_price > 0 %}<tr><td style="padding:6px 0;font-size:14px;color:#374151;">Discount</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">-{{ order.discount_price | money }}</td></tr>{% endif %}⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">Delivery</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.delivery_price | money }}</td></tr>⏎<tr><td style="padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;">Total</td><td align="right" style="padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;">{{ order.total_price | money }}</td></tr>⏎{% if order.paid_amount > 0 %}<tr><td style="padding:6px 0;font-size:14px;color:#374151;">Paid</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.paid_amount | money }}</td></tr>{% endif %}⏎{% if order.cod_amount > 0 %}<tr><td style="padding:6px 0;font-size:14px;color:#374151;"><strong>To pay on delivery</strong></td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;"><strong>{{ order.cod_amount | money }}</strong></td></tr>{% endif %}⏎</table>⏎</td></tr>⏎{% if order.shipping_address.address %}<tr><td style="padding:20px 32px 0;">⏎<p style="margin:0 0 6px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;">Delivery address</p>⏎<p style="margin:0;font-size:14px;line-height:1.6;color:#374151;">{{ order.shipping_address.name }}<br>{{ order.shipping_address.address }}{% if order.shipping_address.area %}, {{ order.shipping_address.area }}{% endif %}{% if order.shipping_address.district %}, {{ order.shipping_address.district }}{% endif %}<br>{{ order.shipping_address.phone }}</p>⏎</td></tr>{% endif %}⏎<tr><td style="padding:28px 32px 28px;">⏎<p style="margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>⏎</td></tr>⏎</table>⏎</td></tr>⏎</table>⏎</body>⏎</html>', '⏎', char(10)), '2026-10-25T00:10:46.166Z', '2026-10-25T00:10:48.139Z', 'Pre-order confirmed', '[]', '00000000-0000-4000-8000-000000000001', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 0, 0);
INSERT INTO "notifications" ("id", "event", "channel", "is_enabled", "subject", "template", "created_at", "updated_at", "name", "conditions", "merchant_id", "wa_name", "wa_language", "wa_status", "wa_reason", "wa_template_id", "wa_params", "wa_body", "wa_version", "wa_checked_at", "reply_buttons", "wa_buttons") VALUES ('7008db54-1060-4245-81a0-a951bd68b75a', 'PAYMENT_RECEIVED', 'EMAIL', 0, 'Payment received for order {{ order.name }}', replace('{% assign accent = shop.accent_color | default: "#111827" %}<!doctype html>⏎<html lang="en">⏎<head>⏎<meta charset="utf-8">⏎<meta name="viewport" content="width=device-width, initial-scale=1">⏎<title>We received your payment</title>⏎</head>⏎<body style="margin:0;padding:0;background:#f4f5f7;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f5f7;">⏎<tr><td align="center" style="padding:32px 12px;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;">⏎<tr><td style="padding:28px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>⏎<td>{% if shop.logo_url %}<img src="{{ shop.logo_url }}" alt="{{ shop.name }}" height="36" style="display:block;height:36px;max-width:180px;border:0;">{% else %}<span style="font-size:20px;font-weight:700;color:#111827;">{{ shop.name }}</span>{% endif %}</td>⏎<td align="right" style="font-size:13px;color:#6b7280;">{% if order.name %}Order {{ order.name }}{% endif %}</td>⏎</tr></table>⏎</td></tr>⏎<tr><td style="padding:24px 32px 4px;">⏎<h1 style="margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;">We received your payment</h1>⏎<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">Hi {{ customer.first_name | default: "there" }}, we received <strong>{{ payment.amount | money }}</strong> for order {{ order.name }}. Thank you!</p>⏎{% if order.due_amount > 0 %}<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">Still to pay on delivery: <strong>{{ order.due_amount | money }}</strong>.</p>{% endif %}⏎</td></tr>⏎⏎<tr><td style="padding:8px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-top:1px solid #e5e7eb;">⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">Order</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.name }}</td></tr>⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">Items</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.item_count }}</td></tr>⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">Total</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.total_price | money }}</td></tr>⏎{% if order.cod_amount > 0 %}<tr><td style="padding:6px 0;font-size:14px;color:#374151;">To pay on delivery</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.cod_amount | money }}</td></tr>{% endif %}⏎</table>⏎</td></tr>⏎<tr><td style="padding:28px 32px 28px;">⏎<p style="margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>⏎</td></tr>⏎</table>⏎</td></tr>⏎</table>⏎</body>⏎</html>', '⏎', char(10)), '2026-10-25T00:10:46.009Z', '2026-10-25T00:10:48.139Z', 'Payment received', '[]', '00000000-0000-4000-8000-000000000001', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 0, 0);
INSERT INTO "notifications" ("id", "event", "channel", "is_enabled", "subject", "template", "created_at", "updated_at", "name", "conditions", "merchant_id", "wa_name", "wa_language", "wa_status", "wa_reason", "wa_template_id", "wa_params", "wa_body", "wa_version", "wa_checked_at", "reply_buttons", "wa_buttons") VALUES ('c3995af8-b1f6-4e9e-9c27-a899c69bfc09', 'RETURN_INITIATED', 'EMAIL', 0, 'Order {{ order.name }} is being returned', replace('{% assign accent = shop.accent_color | default: "#111827" %}<!doctype html>⏎<html lang="en">⏎<head>⏎<meta charset="utf-8">⏎<meta name="viewport" content="width=device-width, initial-scale=1">⏎<title>Your order is being returned</title>⏎</head>⏎<body style="margin:0;padding:0;background:#f4f5f7;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f5f7;">⏎<tr><td align="center" style="padding:32px 12px;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;">⏎<tr><td style="padding:28px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>⏎<td>{% if shop.logo_url %}<img src="{{ shop.logo_url }}" alt="{{ shop.name }}" height="36" style="display:block;height:36px;max-width:180px;border:0;">{% else %}<span style="font-size:20px;font-weight:700;color:#111827;">{{ shop.name }}</span>{% endif %}</td>⏎<td align="right" style="font-size:13px;color:#6b7280;">{% if order.name %}Order {{ order.name }}{% endif %}</td>⏎</tr></table>⏎</td></tr>⏎<tr><td style="padding:24px 32px 4px;">⏎<h1 style="margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;">Your order is being returned</h1>⏎<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">Hi {{ customer.first_name | default: "there" }}, the parcel for order {{ order.name }} is on its way back to us.</p>⏎<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">Questions? Reply to this email{% if shop.phone %} or call us at {{ shop.phone }}{% endif %}.</p>⏎</td></tr>⏎⏎⏎<tr><td style="padding:28px 32px 28px;">⏎<p style="margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>⏎</td></tr>⏎</table>⏎</td></tr>⏎</table>⏎</body>⏎</html>', '⏎', char(10)), '2026-10-25T00:10:46.166Z', '2026-10-25T00:10:48.139Z', 'Return initiated', '[]', '00000000-0000-4000-8000-000000000001', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 0, 0);
INSERT INTO "notifications" ("id", "event", "channel", "is_enabled", "subject", "template", "created_at", "updated_at", "name", "conditions", "merchant_id", "wa_name", "wa_language", "wa_status", "wa_reason", "wa_template_id", "wa_params", "wa_body", "wa_version", "wa_checked_at", "reply_buttons", "wa_buttons") VALUES ('def5bff8-9786-4620-8d87-ebec24afc8bb', 'PAYMENT_FAILED', 'EMAIL', 0, 'Payment for order {{ order.name }} did not go through', replace('{% assign accent = shop.accent_color | default: "#111827" %}<!doctype html>⏎<html lang="en">⏎<head>⏎<meta charset="utf-8">⏎<meta name="viewport" content="width=device-width, initial-scale=1">⏎<title>Your payment didn''t go through</title>⏎</head>⏎<body style="margin:0;padding:0;background:#f4f5f7;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f5f7;">⏎<tr><td align="center" style="padding:32px 12px;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;">⏎<tr><td style="padding:28px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>⏎<td>{% if shop.logo_url %}<img src="{{ shop.logo_url }}" alt="{{ shop.name }}" height="36" style="display:block;height:36px;max-width:180px;border:0;">{% else %}<span style="font-size:20px;font-weight:700;color:#111827;">{{ shop.name }}</span>{% endif %}</td>⏎<td align="right" style="font-size:13px;color:#6b7280;">{% if order.name %}Order {{ order.name }}{% endif %}</td>⏎</tr></table>⏎</td></tr>⏎<tr><td style="padding:24px 32px 4px;">⏎<h1 style="margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;">Your payment didn''t go through</h1>⏎<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">Hi {{ customer.first_name | default: "there" }}, your payment of <strong>{{ payment.amount | money }}</strong> for order {{ order.name }} did not go through. No money was taken. You can try again below.</p>⏎</td></tr>⏎{% if order.status_url %}<tr><td style="padding:12px 32px 4px;">⏎<a href="{{ order.status_url }}" style="display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;">Try again</a>⏎</td></tr>{% endif %}⏎<tr><td style="padding:8px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-top:1px solid #e5e7eb;">⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">Order</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.name }}</td></tr>⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">Items</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.item_count }}</td></tr>⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">Total</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.total_price | money }}</td></tr>⏎{% if order.cod_amount > 0 %}<tr><td style="padding:6px 0;font-size:14px;color:#374151;">To pay on delivery</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.cod_amount | money }}</td></tr>{% endif %}⏎</table>⏎</td></tr>⏎<tr><td style="padding:28px 32px 28px;">⏎<p style="margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>⏎</td></tr>⏎</table>⏎</td></tr>⏎</table>⏎</body>⏎</html>', '⏎', char(10)), '2026-10-25T00:10:46.166Z', '2026-10-25T00:10:48.139Z', 'Payment failed', '[]', '00000000-0000-4000-8000-000000000001', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 0, 0);
INSERT INTO "notifications" ("id", "event", "channel", "is_enabled", "subject", "template", "created_at", "updated_at", "name", "conditions", "merchant_id", "wa_name", "wa_language", "wa_status", "wa_reason", "wa_template_id", "wa_params", "wa_body", "wa_version", "wa_checked_at", "reply_buttons", "wa_buttons") VALUES ('c8c3e3d3-3347-4872-aebe-776cb40fbae4', 'ORDER_SHIPPED', 'EMAIL', 0, 'Order {{ order.name }} is on the way', replace('{% assign accent = shop.accent_color | default: "#111827" %}<!doctype html>⏎<html lang="en">⏎<head>⏎<meta charset="utf-8">⏎<meta name="viewport" content="width=device-width, initial-scale=1">⏎<title>Your order is on the way</title>⏎</head>⏎<body style="margin:0;padding:0;background:#f4f5f7;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f5f7;">⏎<tr><td align="center" style="padding:32px 12px;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;">⏎<tr><td style="padding:28px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>⏎<td>{% if shop.logo_url %}<img src="{{ shop.logo_url }}" alt="{{ shop.name }}" height="36" style="display:block;height:36px;max-width:180px;border:0;">{% else %}<span style="font-size:20px;font-weight:700;color:#111827;">{{ shop.name }}</span>{% endif %}</td>⏎<td align="right" style="font-size:13px;color:#6b7280;">{% if order.name %}Order {{ order.name }}{% endif %}</td>⏎</tr></table>⏎</td></tr>⏎<tr><td style="padding:24px 32px 4px;">⏎<h1 style="margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;">Your order is on the way</h1>⏎<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">Hi {{ customer.first_name | default: "there" }}, your order {{ order.name }} has been handed to {{ shipment.courier | default: "the courier" }